// Live generators (OT fork): what keeps running while the sequencer plays.
//
//  * BBCut play modes B1..B10: their cut tables are rebuilt whenever the
//    sequencer is stopped, so every play start gets a new cut set.
//  * Acid "Mutate": a track generated by Acid with Mutate > 0 re-rolls part
//    of its line at each loop end (TB-3PO's mutate), until it is generated
//    again with Mutate 0 (Lock). Two tracks at a time, like TB-3PO's A / B.
#pragma once

#include <cstdint>

#include "gen/gen.h"

namespace ot {

class App;

namespace live {

constexpr int kAcidSlots = 2;

// Main loop, every pass (App::loop).
void service(App& a);
// Starts (Mutate > 0) or stops (Mutate 0) the live acid of target track t.t0.
// v = the Acid parameters, rngSeed = gen::Result::rngSeed of the generate.
void acid(App& a, const int16_t* v, const gen::Target& t, uint32_t rngSeed);
bool acidActive(int track);
void stopAll();

}  // namespace live
}  // namespace ot
